11:   if (!navToggle || !navMenu) {
12:     return;
13:   }
14: 
15:   var MOBILE_BREAKPOINT = 768;
16: 
17:   function setMenuState(isOpen) {
18:     navMenu.classList.toggle("is-open", isOpen);
19:     navToggle.classList.toggle("is-open", isOpen);
20:     navToggle.setAttribute("aria-expanded", String(isOpen));
21:     navToggle.setAttribute(
22:       "aria-label",
23:       isOpen ? "Close navigation menu" : "Open navigation menu"
24:     );
25:   }
26: 
27:   /* Ensure clean initial state */
28:   setMenuState(false);
29: 
30:   /* Toggle menu on hamburger button click */
31:   navToggle.addEventListener("click", function () {
32:     var currentlyOpen = navToggle.getAttribute("aria-expanded") === "true";
33:     setMenuState(!currentlyOpen);
34:   });
35: 
36:   /* Close menu when a navigation link is selected on mobile */
37:   navMenu.addEventListener("click", function (event) {
38:     if (event.target.closest("a")) {
39:       setMenuState(false);
40:     }
41:   });
42: 
43:   /* Close menu on Escape key and return focus to toggle button */
44:   document.addEventListener("keydown", function (event) {
45:     if (event.key === "Escape" && navToggle.getAttribute("aria-expanded") === "true") {
46:       setMenuState(false);
