$navLinksDetails = [regex]::Matches($detailsHtml, '<a class="nav-link[^"]*" href="([^"]+)"[^>]*>([^<]+)</a>') | ForEach-Object { "$($_.Groups[1].Value)|$($_.Groups[2].Value)" }
