if (!Array.prototype.forEach) {
  Array.prototype.forEach = function(cb) { for (var i = 0; i < this.length; i++) cb(this[i], i, this); };
}
if (!Array.prototype.indexOf) {
  Array.prototype.indexOf = function(val) { for (var i = 0; i < this.length; i++) if (this[i] === val) return i; return -1; };
}
if (!Array.isArray) {
  Array.isArray = function(v) { return Object.prototype.toString.call(v) === "[object Array]"; };
}
if (!String.prototype.trim) {
  String.prototype.trim = function() { return this.replace(/^\s+|\s+$/g, ""); };
}
var JSON = {
  parse: function(s) { return eval("(" + s + ")"); },
  stringify: function(arr) {
    var out = [];
    for (var i = 0; i < arr.length; i++) out.push('"' + String(arr[i]).replace(/"/g, '\\"') + '"');
    return "[" + out.join(",") + "]";
  }
};

var store = {};
function runScenario(searchStr, toggleSave) {
  var elementsById = {};
  function makeEl(tag, id) {
    var el = {
      tagName: tag, id: id || "", className: "", textContent: "", innerHTML: "",
      hidden: false, children: [], attrs: {}, listeners: {},
      classList: { _set: {}, toggle: function(cls, force) { this._set[cls] = !!force; } },
      setAttribute: function(k, v) { this.attrs[k] = String(v); },
      getAttribute: function(k) { return this.attrs[k] || null; },
      appendChild: function(c) { this.children.push(c); return c; },
      insertBefore: function(c) { this.children.unshift(c); return c; },
      querySelector: function() { return null; },
      addEventListener: function(ev, fn) { this.listeners[ev] = fn; },
      remove: function() {}
    };
    if (id) elementsById[id] = el;
    return el;
  }
  var ids = ["breadcrumb-current","recipe-detail-view","recipe-not-found","recipe-media","recipe-time-badge","recipe-category","recipe-title","recipe-description","recipe-author","recipe-prep-time","recipe-cook-time","recipe-servings","recipe-difficulty","save-recipe-btn","save-status-msg","recipe-ingredients-list","recipe-steps-list","steps-count-note","recipe-tags-list"];
  for (var i = 0; i < ids.length; i++) makeEl("div", ids[i]);

  var domReadyFn = null;
  var document = {
    title: "",
    addEventListener: function(ev, fn) { if (ev === "DOMContentLoaded") domReadyFn = fn; },
    getElementById: function(id) { return elementsById[id] || null; },
    createElement: function(tag) { return makeEl(tag); },
    createElementNS: function(ns, tag) { return makeEl(tag); }
  };
  var window = {
    location: { search: searchStr },
    localStorage: {
      getItem: function(k) { return store.hasOwnProperty(k) ? store[k] : null; },
      setItem: function(k, v) { store[k] = String(v); }
    }
  };
  function URLSearchParams(qs) {
    this.map = {};
    var clean = (qs || "").replace(/^\?/, "");
    if (clean) {
      var parts = clean.split("&");
      for (var j = 0; j < parts.length; j++) {
        var kv = parts[j].split("=");
        this.map[decodeURIComponent(kv[0])] = decodeURIComponent(kv[1] || "");
      }
    }
  }
  URLSearchParams.prototype.get = function(k) { return this.map.hasOwnProperty(k) ? this.map[k] : null; };

  __RECIPE_JS__
  domReadyFn();
  if (toggleSave && elementsById["save-recipe-btn"].listeners["click"]) {
    elementsById["save-recipe-btn"].listeners["click"]();
  }
  WScript.Echo(searchStr + " (click=" + toggleSave + ") => saveText=\"" + elementsById["save-recipe-btn"].textContent + "\" | pressed=" + elementsById["save-recipe-btn"].getAttribute("aria-pressed") + " | storage=" + (store["forkAndShare_savedRecipes"] || "[]"));
}

